"""Optional Claude summary of a changed page (FR-A1..A5). Marked AI-generated by the digest."""
import json, os, urllib.request

def summarise(opp, text, profile, env=None, opener=urllib.request.urlopen):
    env = env if env is not None else os.environ
    key = env.get("ANTHROPIC_API_KEY")
    if not key: return None
    prompt = (f"Profile: {json.dumps(profile)}\nOpportunity: {opp['name']} ({opp['university']})\nPage text:\n{text[:12000]}\n\n"
              "In at most 3 bullets state value, deadline, and whether Austrian or Spanish (EU) citizens can apply. "
              "Quote the page for each claim. Write 'unclear' instead of guessing.")
    body = {"model": "claude-sonnet-5-5", "max_tokens": 400, "messages": [{"role": "user", "content": prompt}]}
    req = urllib.request.Request("https://api.anthropic.com/v1/messages", json.dumps(body).encode(),
                                 {"x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json"})
    try:
        with opener(req, timeout=60) as r: return json.load(r)["content"][0]["text"]
    except Exception as e:
        return f"(AI summary failed, extractive output used: {type(e).__name__})"
